package com.sloth.client.screen;
import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import java.util.*;
public final class ServerDisplayScreen extends SlothScreen {
 private final Screen parent;private int x,y,w,h,offset;private List<String> lines=List.of();private String reloadStatus="";private boolean reloading;public ServerDisplayScreen(Screen p){super(Component.literal("Server display help"));parent=p;}
 protected void init(){w=Math.min(540,width-24);h=Math.min(330,height-20);x=(width-w)/2;y=(height-h)/2;var report=new ArrayList<String>();String issue=com.sloth.client.PackDiagnostics.issue();report.add(issue.isEmpty()?"No resource-pack failures detected in this session.":"Detected: "+issue);var packs=minecraft.getResourceManager().listPacks().map(p->p.packId()).toList();if(!reloadStatus.isBlank())report.add(reloadStatus);report.addAll(com.sloth.client.PackDiagnostics.notices().stream().filter(n->!n.equals(issue)).toList());report.add("Active resource packs: "+packs.size());report.addAll(packs.stream().map(p->"• "+p).toList());var fonts=minecraft.getResourceManager().getResourceStack(Identifier.fromNamespaceAndPath("minecraft","font/default.json"));report.add("Default-font providers: "+fonts.size());report.add("Square badges usually mean a missing glyph or a pack that did not load.");report.add("Enable Server Resource Packs in Edit Server, then reconnect.");report.add("Check Game Log for resource-pack download or font errors.");report.add("Server text and Tab use their own fonts; Sloth's menu font is separate.");report.add("Protocol translation can affect packs. Try the server's native version.");var wrapped=new ArrayList<String>();for(String line:report){while(!line.isEmpty()){String part=font.plainSubstrByWidth(line,w-28);if(part.isEmpty())break;wrapped.add(part);line=line.substring(part.length()).stripLeading();}}lines=wrapped;offset=Math.min(offset,Math.max(0,lines.size()-Math.max(1,(h-88)/16)));int bw=(w-42)/4;button(x+14,y+h-32,bw,20,"Refresh",b->rebuildWidgets());button(x+20+bw,y+h-32,bw,20,"Game Log",b->net.minecraft.util.Util.getPlatform().openFile(minecraft.gameDirectory.toPath().resolve("logs").toFile()));var reload=button(x+26+bw*2,y+h-32,bw,20,"Reload packs",b->{if(reloading)return;reloading=true;b.active=false;com.sloth.client.PackDiagnostics.clear();reloadStatus="Reloading selected packs…";minecraft.reloadResourcePacks().whenComplete((v,e)->minecraft.execute(()->{reloading=false;reloadStatus=e==null?"Reload completed. Missing downloads still require reconnecting.":"Reload failed. Review the Game Log.";rebuildWidgets();}));});reload.active=!reloading;button(x+32+bw*3,y+h-32,bw,20,"Back",b->onClose());}
 public void renderBackground(GuiGraphics g,int mx,int my,float t){super.renderBackground(g,mx,my,t);Ui.panel(g,x,y,w,h,Ui.BG);}public void render(GuiGraphics g,int mx,int my,float t){super.render(g,mx,my,t);g.drawString(font,"SERVER DISPLAY HELP",x+14,y+14,Ui.TEXT,false);int py=y+38;for(String line:lines.stream().skip(offset).toList()){if(py>y+h-50)break;g.drawString(font,Ui.ellipsize(font,line,w-28),x+14,py,Ui.MUTED,false);py+=16;}}public boolean mouseScrolled(double mx,double my,double sx,double sy){offset=Math.max(0,Math.min(Math.max(0,lines.size()-Math.max(1,(h-88)/16)),offset-(int)Math.signum(sy)));return true;}public void onClose(){minecraft.setScreen(parent);}
}
